{
  "findings": [
    {
      "check_id": "CKV_GCP_6",
      "title": "Unencrypted Google Compute Disk",
      "resource": "google_compute_disk.changeme_count_attached_disk_disk",
      "severity": "HIGH",
      "explanation": "The Google Compute Disk does not have encryption specified. Without encryption, sensitive data stored on the disk could be exposed if the disk is compromised."
    }
  ],
  "patched_code": "resource \"google_compute_disk\" \"changeme_count_attached_disk_disk\" {\n  name                      = \"changeme-count-attached-disk-disk-${count.index}\"\n  count                     = var.changeme_google_attached_disk_count_number_of_instances\n  type                      = \"pd-ssd\"\n  zone                      = \"us-central1-a\"\n  size                      = 4\n  physical_block_size_bytes = 4096\n  disk_encryption_key {\n    kms_key_self_link = var.kms_key_self_link\n  }\n}",
  "fix_summary": "Added a `disk_encryption_key` block to specify encryption for the Google Compute Disk, ensuring data is encrypted at rest."
}
